import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useToastStore } from '../../store/useToastStore';
import { CheckCircle, XCircle, AlertCircle, Info, X } from 'lucide-react';

const icons = {
  success: <CheckCircle className="w-5 h-5 text-emerald-500" />,
  error: <XCircle className="w-5 h-5 text-rose-500" />,
  warning: <AlertCircle className="w-5 h-5 text-amber-500" />,
  info: <Info className="w-5 h-5 text-blue-500" />
};

export const ToastContainer = () => {
  const { toasts, removeToast } = useToastStore();

  return (
    <div className="fixed top-4 right-4 z-50 flex flex-col gap-2 pointer-events-none">
      <AnimatePresence>
        {toasts.map((toast) => (
          <motion.div
            key={toast.id}
            initial={{ opacity: 0, y: -20, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, scale: 0.9, transition: { duration: 0.2 } }}
            className="pointer-events-auto flex items-center gap-3 min-w-[300px] p-4 rounded-lg bg-white border border-slate-200 shadow-lg"
          >
            {icons[toast.type] || icons.info}
            <p className="flex-1 text-sm font-medium text-slate-800">
              {toast.message}
            </p>
            <button
              onClick={() => removeToast(toast.id)}
              className="text-slate-400 hover:text-slate-600 transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
          </motion.div>
        ))}
      </AnimatePresence>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { Card, CardBody } from '../../components/ui/Card';
import { Badge } from '../../components/ui/Badge';
import { Button } from '../../components/ui/Button';
import apiClient from '../../services/apiClient';
import { motion, AnimatePresence } from 'framer-motion';
import { FileSearch, X, FileText, Search, Filter, Clock, Activity, CheckCircle, XCircle, RefreshCw } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

export const AntreanSurat = () => {
  const navigate = useNavigate();
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

  const [filterStatus, setFilterStatus] = useState('semua');
  const [sortTime, setSortTime] = useState('terbaru');
  const [filterJenis, setFilterJenis] = useState('semua');
  const [jenisSuratList, setJenisSuratList] = useState([]);

  // Modal State
  const [isModalOpen, setModalOpen] = useState(false);
  const [selectedPengajuan, setSelectedPengajuan] = useState(null);
  const [updateForm, setUpdateForm] = useState({ status_baru: '', catatan: '' });
  const [updating, setUpdating] = useState(false);

  const fetchData = async () => {
    try {
      setLoading(true);
      const res = await apiClient.get(`/admin/pengajuan?t=${new Date().getTime()}`);
      if (res.data.success) {
        setData(res.data.data);
      }
    } catch (error) {
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    const fetchJenis = async () => {
      try {
        const res = await apiClient.get('/pengajuan/jenis-surat');
        if (res.data.success) {
          setJenisSuratList(res.data.data);
        }
      } catch (error) {}
    };
    fetchJenis();
  }, []);

  const openActionModal = (pengajuan) => {
    navigate(`/admin/pengajuan/${pengajuan.id_pengajuan}`);
  };

  // Helper status color mapping
  const getStatusBadge = (status) => {
    switch(status) {
      case 'selesai': return <Badge className="bg-emerald-100 text-emerald-700 border border-emerald-200">Selesai</Badge>;
      case 'ditolak': return <Badge className="bg-rose-100 text-rose-700 border border-rose-200">Ditolak Admin</Badge>;
      case 'ditolak_kades': return <Badge className="bg-rose-100 text-rose-700 border border-rose-200">Ditolak Kades</Badge>;
      case 'diproses': return <Badge className="bg-amber-100 text-amber-700 border border-amber-200">Diproses Kades</Badge>;
      default: return <Badge className="bg-slate-100 text-slate-700 border border-slate-200">Menunggu Verifikasi</Badge>;
    }
  };

  // Filter and Sort Logic
  const filteredData = useMemo(() => {
    let result = [...data];
    if (filterStatus !== 'semua') {
      result = result.filter(item => item.status === filterStatus);
    }
    if (filterJenis !== 'semua') {
      result = result.filter(item => item.nama_surat === filterJenis);
    }

    // Sort by ID to approximate time (assuming auto increment ID)
    result.sort((a, b) => {
      if (sortTime === 'terbaru') {
        return b.id_pengajuan - a.id_pengajuan;
      } else {
        return a.id_pengajuan - b.id_pengajuan;
      }
    });

    return result;
  }, [data, filterStatus, filterJenis, sortTime]);

  return (
    <div className="w-full h-full flex-1 flex flex-col min-h-0 max-w-7xl mx-auto">
      {/* Judul Halaman kini telah dipindah ke bagian Navbar (AdminLayout) */}

      {/* Filter and Actions Bar */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 shrink-0">
        <div className="flex flex-wrap items-center gap-3">
          <Button 
            variant="outline" 
            onClick={fetchData} 
            disabled={loading}
            className="rounded-xl border-slate-200 text-slate-600 hover:bg-slate-50 flex items-center gap-2"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            <span className="hidden sm:inline">Segarkan</span>
          </Button>

          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Filter className="w-4 h-4 text-slate-400" />
            </div>
            <select
              className="pl-9 pr-8 py-2 bg-white border border-slate-200 rounded-xl text-sm font-bold text-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 appearance-none shadow-sm cursor-pointer"
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
            >
              <option value="semua">Semua Status</option>
              <option value="menunggu">Menunggu</option>
              <option value="diproses">Diproses Kades</option>
              <option value="selesai">Selesai / Terbit</option>
              <option value="ditolak">Ditolak Admin</option>
              <option value="ditolak_kades">Ditolak Kades</option>
            </select>
          </div>

          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Clock className="w-4 h-4 text-slate-400" />
            </div>
            <select
              className="pl-9 pr-8 py-2 bg-white border border-slate-200 rounded-xl text-sm font-bold text-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 appearance-none shadow-sm cursor-pointer"
              value={sortTime}
              onChange={(e) => setSortTime(e.target.value)}
            >
              <option value="terbaru">Terbaru</option>
              <option value="terlama">Terlama</option>
            </select>
          </div>

          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <FileText className="w-4 h-4 text-slate-400" />
            </div>
            <select
              className="pl-9 pr-8 py-2 bg-white border border-slate-200 rounded-xl text-sm font-bold text-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 appearance-none shadow-sm cursor-pointer w-56 truncate"
              value={filterJenis}
              onChange={(e) => setFilterJenis(e.target.value)}
            >
              <option value="semua">Semua Jenis Layanan</option>
              {jenisSuratList.map((jenis, idx) => (
                <option key={jenis.id_jenis || idx} value={jenis.nama_surat}>
                  {jenis.nama_surat}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div className="text-sm font-bold text-slate-400 px-2">
          Menampilkan <span className="text-blue-600">{filteredData.length}</span> data
        </div>
      </div>

      <Card className="border-0 shadow-sm rounded-2xl bg-white mt-4 flex flex-col flex-1 min-h-0 overflow-hidden">
        <div className="overflow-auto flex-1">
          <div className="w-full min-w-max">
            <table className="w-full text-left border-separate border-spacing-0">
              <thead className="z-20 relative">
                <tr>
                  <th className="sticky top-0 px-6 py-4 text-xs font-bold text-blue-800 tracking-wide w-32 border-b border-blue-100 bg-blue-50 z-20">Kode / Tgl</th>
                  <th className="sticky top-0 px-6 py-4 text-xs font-bold text-blue-800 tracking-wide border-b border-blue-100 bg-blue-50 z-20">Identitas Warga</th>
                  <th className="sticky top-0 px-6 py-4 text-xs font-bold text-blue-800 tracking-wide border-b border-blue-100 bg-blue-50 z-20">Jenis Layanan</th>
                  <th className="sticky top-0 px-6 py-4 text-xs font-bold text-blue-800 tracking-wide border-b border-blue-100 bg-blue-50 z-20">Status</th>
                  <th className="sticky top-0 px-6 py-4 text-xs font-bold text-blue-800 tracking-wide text-right border-b border-blue-100 bg-blue-50 z-20">Aksi</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50 relative z-0">
                <AnimatePresence>
                  {loading ? (
                    <tr>
                      <td colSpan="5" className="px-6 py-20 text-center">
                        <div className="flex flex-col items-center gap-3 opacity-50">
                          <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                          <p className="text-sm font-medium text-slate-500">Memuat data antrean...</p>
                        </div>
                      </td>
                    </tr>
                  ) : filteredData.length === 0 ? (
                    <tr>
                      <td colSpan="5" className="px-6 py-20 text-center">
                        <div className="flex flex-col items-center gap-3 opacity-50">
                          <FileSearch className="w-12 h-12 text-slate-400" />
                          <p className="text-sm font-medium text-slate-500">Tidak ada antrean yang sesuai filter.</p>
                        </div>
                      </td>
                    </tr>
                  ) : (
                    filteredData.map((row, index) => (
                      <motion.tr 
                        key={row.id_pengajuan}
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.2, delay: (index % 10) * 0.05 }}
                        className="hover:bg-blue-50/40 transition-colors group"
                      >
                        <td className="px-6 py-4">
                          <p className="text-sm font-mono font-black text-slate-800">{row.kode_tracking}</p>
                          <p className="text-xs text-slate-400 mt-1">{row.tgl_pengajuan}</p>
                        </td>
                        <td className="px-6 py-4">
                          <p className="text-sm font-bold text-slate-800">{row.nama_lengkap}</p>
                          <p className="text-xs font-mono text-slate-500 mt-1">{row.nik}</p>
                        </td>
                        <td className="px-6 py-4">
                          <div className="flex items-center gap-2">
                            <p className="text-xs font-semibold text-slate-700 max-w-[200px] truncate" title={row.nama_surat}>{row.nama_surat}</p>
                          </div>
                        </td>
                        <td className="px-6 py-4">
                          {getStatusBadge(row.status)}
                        </td>
                        <td className="px-6 py-4 text-right">
                          <Button 
                            variant="outline" 
                            size="sm" 
                            className="rounded-xl border-slate-200 text-slate-600 hover:text-blue-700 hover:border-blue-200 hover:bg-blue-50 font-semibold" 
                            onClick={() => openActionModal(row)}
                          >
                            <Search className="w-4 h-4 mr-2" /> Tinjau
                          </Button>
                        </td>
                      </motion.tr>
                    ))
                  )}
                </AnimatePresence>
              </tbody>
            </table>
          </div>
        </div>
      </Card>
    </div>
  );
};

import React, { useEffect, useState } from 'react'; // HMR trigger
import { Card, CardBody } from '../../components/ui/Card';
import { Clock, FileText, CheckCircle, Activity, XCircle } from 'lucide-react';
import apiClient from '../../services/apiClient';
import { motion } from 'framer-motion';
import { Link, useNavigate } from 'react-router-dom';
import { ChevronRight, Inbox } from 'lucide-react';
import { format } from 'date-fns';
import { id } from 'date-fns/locale';

const StatCard = ({ title, count, icon, bgColor, iconColor, delay }) => (
  <motion.div
    initial={{ opacity: 0, y: 20 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ duration: 0.4, delay }}
  >
    <Card className="border border-slate-100 shadow-sm hover:shadow-md transition-all duration-300 group relative overflow-hidden bg-white">
      <div className={`absolute top-0 right-0 w-32 h-32 ${bgColor} opacity-20 rounded-bl-[100px] -mr-8 -mt-8 transition-transform group-hover:scale-110`} />
      <CardBody className="p-6">
        <div className="flex justify-between items-start relative z-10">
          <div>
            <p className="text-xs font-bold text-slate-500 mb-2 uppercase tracking-wider">{title}</p>
            <h3 className="text-4xl font-black text-slate-800 tracking-tighter">{count}</h3>
          </div>
          <div className={`p-4 rounded-2xl ${bgColor} ${iconColor} shadow-inner`}>
            {icon}
          </div>
        </div>
      </CardBody>
    </Card>
  </motion.div>
);

export const Dashboard = () => {
  const navigate = useNavigate();
  const [stats, setStats] = useState({ menunggu: 0, diproses: 0, selesai: 0, ditolak: 0 });
  const [recentPending, setRecentPending] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const res = await apiClient.get('/admin/pengajuan');
        if (res.data.success) {
          const data = res.data.data;

          const menungguList = data.filter(d => d.status === 'menunggu');

          setStats({
            menunggu: menungguList.length,
            diproses: data.filter(d => d.status === 'diproses').length,
            selesai: data.filter(d => d.status === 'selesai').length,
            ditolak: data.filter(d => d.status === 'ditolak').length,
          });

          setRecentPending(menungguList.slice(0, 3));
        }
      } catch (e) { 
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetchStats();
  }, []);

  return (
    <div className="w-full max-w-7xl mx-auto">
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard 
            title="Menunggu" 
            count={stats.menunggu} 
            icon={<Clock className="w-6 h-6" />} 
            bgColor="bg-amber-100" 
            iconColor="text-amber-600"
            delay={0.1}
          />
          <StatCard 
            title="Diproses" 
            count={stats.diproses} 
            icon={<Activity className="w-6 h-6" />} 
            bgColor="bg-blue-100" 
            iconColor="text-blue-600"
            delay={0.2}
          />
          <StatCard 
            title="Selesai" 
            count={stats.selesai} 
            icon={<CheckCircle className="w-6 h-6" />} 
            bgColor="bg-emerald-100" 
            iconColor="text-emerald-600"
            delay={0.3}
          />
          <StatCard 
            title="Ditolak" 
            count={stats.ditolak} 
            icon={<XCircle className="w-6 h-6" />} 
            bgColor="bg-rose-100" 
            iconColor="text-rose-600"
            delay={0.4}
          />
      </div>

      {/* Bagian Bawah: Antrean Perlu Perhatian */}
      <div className="mt-8">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h2 className="text-lg font-black text-slate-800">Antrean Perlu Perhatian</h2>
            <p className="text-sm text-slate-500">Permohonan terbaru yang belum diverifikasi.</p>
          </div>
          <Link to="/admin/pengajuan" className="text-sm font-bold text-blue-600 hover:text-blue-700 flex items-center gap-1">
            Lihat Semua Antrean <ChevronRight className="w-4 h-4" />
          </Link>
        </div>

        {loading ? (
          <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-100 flex justify-center text-slate-400">
            Memuat data...
          </div>
        ) : recentPending.length === 0 ? (
          <div className="bg-white p-12 rounded-2xl shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
            <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mb-4">
              <CheckCircle className="w-8 h-8 text-emerald-500" />
            </div>
            <h3 className="font-bold text-slate-800 mb-1">Semua Bersih!</h3>
            <p className="text-sm text-slate-500">Tidak ada antrean surat baru yang menunggu untuk diproses saat ini.</p>
          </div>
        ) : (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-slate-50/80 border-b border-slate-100 text-[11px] uppercase tracking-wider text-slate-500 font-bold">
                    <th className="py-4 px-6 whitespace-nowrap">Pemohon</th>
                    <th className="py-4 px-6 whitespace-nowrap">Layanan</th>
                    <th className="py-4 px-6 whitespace-nowrap">Waktu Masuk</th>
                    <th className="py-4 px-6 text-right whitespace-nowrap">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {recentPending.map((item, idx) => (
                    <tr key={item.id_pengajuan} className="hover:bg-slate-50/50 transition-colors group">
                      <td className="py-4 px-6">
                        <p className="font-bold text-slate-800 text-sm">{item.nama_lengkap}</p>
                        <p className="text-xs text-slate-500 font-mono mt-0.5">{item.kode_tracking}</p>
                      </td>
                      <td className="py-4 px-6">
                        <span className="inline-flex items-center px-2.5 py-1 rounded-md text-xs font-bold bg-blue-50 text-blue-700">
                          {item.nama_surat}
                        </span>
                      </td>
                      <td className="py-4 px-6">
                        <p className="text-sm text-slate-600 font-medium">
                          {item.tgl_pengajuan 
                            ? format(new Date(item.tgl_pengajuan), 'dd MMM yyyy, HH:mm', { locale: id }) 
                            : '-'}
                        </p>
                      </td>
                      <td className="py-4 px-6 text-right">
                        <button 
                          onClick={() => navigate(`/admin/pengajuan/${item.id_pengajuan}`)}
                          className="inline-flex items-center justify-center px-4 py-2 bg-slate-800 hover:bg-blue-600 text-white text-xs font-bold rounded-lg transition-colors shadow-sm"
                        >
                          Tinjau Berkas
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import apiClient from '../../services/apiClient';
import { Card, CardBody } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Badge } from '../../components/ui/Badge';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronLeft, Clock, Activity, CheckCircle, XCircle, FileText, Image as ImageIcon, Maximize2, X, Download, Loader2 } from 'lucide-react';
import { useHeaderStore } from '../../store/useHeaderStore';

const BASE_URL = import.meta.env.VITE_API_BASE_URL ? import.meta.env.VITE_API_BASE_URL.replace('/api/v1', '') : 'http://localhost:8080';

export const DetailPengajuan = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { setHeader, clearHeader } = useHeaderStore();

  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  const [activeTab, setActiveTab] = useState('detail');

  const [updateForm, setUpdateForm] = useState({ status_baru: 'menunggu', catatan: '', nomor_surat: '' });
  const [updating, setUpdating] = useState(false);

  // State for image viewer modal
  const [viewerOpen, setViewerOpen] = useState(false);
  const [viewerImage, setViewerImage] = useState(null);
  const [viewerTitle, setViewerTitle] = useState('');
  const [pdfUrl, setPdfUrl] = useState('');

  const BASE_URL = import.meta.env.VITE_API_BASE_URL ? import.meta.env.VITE_API_BASE_URL.replace('/api/v1', '') : 'http://localhost:8080';

  useEffect(() => {
    const fetchDetail = async () => {
      try {
        setLoading(true);
        const res = await apiClient.get(`/admin/pengajuan/${id}`);
        if (res.data.success) {
          const fetchedData = res.data.data;
          setData(fetchedData);
          setUpdateForm({
            status_baru: fetchedData.status,
            catatan: fetchedData.alasan_penolakan || ''
          });

          setHeader(
            'Tinjau Pengajuan',
            <>Kode Tracking: <span className="font-mono font-bold text-blue-600">{fetchedData.kode_tracking}</span></>,
            <button 
              onClick={() => navigate('/admin/pengajuan')}
              className="w-12 h-12 flex items-center justify-center rounded-2xl bg-slate-100 hover:bg-slate-200 text-slate-600 transition-colors"
              title="Kembali"
            >
              <ChevronLeft className="w-6 h-6" />
            </button>
          );
        }
      } catch (error) {
        console.error(error);
      } finally {
        setLoading(false);
      }
    };
    fetchDetail();

    return () => {
      clearHeader();
    };
  }, [id, setHeader, clearHeader, navigate]);

  // Fetch PDF Preview
  useEffect(() => {
    if (activeTab === 'preview' && !pdfUrl && data?.status !== 'menunggu') {
      if ((data?.status === 'selesai' || data?.status === 'disetujui_kades') && data?.file_path) {
        setPdfUrl(`${BASE_URL}/${data.file_path}`);
        return;
      }

      const fetchPreview = async () => {
        try {
          const response = await apiClient.get(`/admin/pengajuan/${id}/preview`, {
            responseType: 'blob'
          });
          const url = URL.createObjectURL(new Blob([response.data], { type: 'application/pdf' }));
          setPdfUrl(url);
        } catch (error) {
          console.error("Gagal memuat preview:", error);
        }
      };
      fetchPreview();
    }
  }, [activeTab, id, pdfUrl, data?.status, data?.file_path]);

  // Clean up ObjectURL
  useEffect(() => {
    return () => {
      if (pdfUrl) URL.revokeObjectURL(pdfUrl);
    };
  }, [pdfUrl]);

  const handleUpdate = async (e) => {
    e.preventDefault();
    setUpdating(true);
    try {
      const res = await apiClient.put(`/admin/pengajuan/${id}/status`, updateForm, { showSuccessToast: true });
      if (res.data.success) {
        // Refresh data or navigate back
        navigate('/admin/pengajuan');
      }
    } catch (error) {
      console.error(error);
    } finally {
      setUpdating(false);
    }
  };

  const getStatusBadge = (status) => {
    switch(status) {
      case 'selesai': return <Badge className="bg-emerald-100 text-emerald-700 border border-emerald-200 px-3 py-1">Selesai</Badge>;
      case 'ditolak': return <Badge className="bg-rose-100 text-rose-700 border border-rose-200 px-3 py-1">Ditolak</Badge>;
      case 'diproses': return <Badge className="bg-blue-100 text-blue-700 border border-blue-200 px-3 py-1">Diproses</Badge>;
      default: return <Badge className="bg-amber-100 text-amber-700 border border-amber-200 px-3 py-1">Menunggu</Badge>;
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-64 gap-3">
        <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-slate-500 font-medium">Memuat detail pengajuan...</p>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="flex flex-col items-center justify-center h-64 gap-3">
        <XCircle className="w-12 h-12 text-rose-400" />
        <p className="text-slate-500 font-medium">Data pengajuan tidak ditemukan.</p>
        <Button variant="outline" onClick={() => navigate('/admin/pengajuan')}>Kembali</Button>
      </div>
    );
  }

  // Parse data input
  let parsedDataInput = {};
  try {
    parsedDataInput = JSON.parse(data.data_input || '{}');
  } catch(e) {}

  // Separate files from text data
  const files = [];
  const texts = [];
  let keperluanText = '-';

  Object.keys(parsedDataInput).forEach(key => {
    const val = parsedDataInput[key];
    if (typeof val === 'string' && val.startsWith('/uploads/')) {
      files.push({ key, url: val });
    } else if (key.toLowerCase() === 'keperluan') {
      keperluanText = val;
    } else {
      texts.push({ key, val });
    }
  });

  const openViewer = (title, url) => {
    setViewerTitle(title);
    setViewerImage(`${BASE_URL}${url}`);
    setViewerOpen(true);
  };

  return (
    <div className="max-w-5xl mx-auto h-[calc(100vh-180px)] flex flex-col">
      <Card className="border-0 shadow-sm rounded-2xl bg-white flex-1 flex flex-col overflow-hidden">
        {/* Unified Tab Navigation Header */}
        <div className="flex flex-col sm:flex-row border-b border-slate-200 bg-slate-50/80 shrink-0">
          <button
            onClick={() => setActiveTab('detail')}
            className={`flex-1 px-6 py-4 font-bold text-sm transition-all flex items-center justify-center gap-2 border-b-2 cursor-pointer ${
              activeTab === 'detail' 
                ? 'border-blue-600 text-blue-700 bg-white' 
                : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-100'
            }`}
          >
            <FileText className="w-4 h-4" /> Detail & Input
          </button>
          <button
            onClick={() => setActiveTab('berkas')}
            className={`flex-1 px-6 py-4 font-bold text-sm transition-all flex items-center justify-center gap-2 border-b-2 cursor-pointer ${
              activeTab === 'berkas' 
                ? 'border-blue-600 text-blue-700 bg-white' 
                : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-100'
            }`}
          >
            <ImageIcon className="w-4 h-4" /> Berkas ({files.length})
          </button>
          <button
            onClick={() => setActiveTab('tindak_lanjut')}
            className={`flex-1 px-6 py-4 font-bold text-sm transition-all flex items-center justify-center gap-2 border-b-2 cursor-pointer ${
              activeTab === 'tindak_lanjut' 
                ? 'border-blue-600 text-blue-700 bg-white' 
                : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-100'
            }`}
          >
            <Activity className="w-4 h-4" /> Tindak Lanjut
          </button>
          <button
            disabled={data.status === 'menunggu'}
            title={data.status === 'menunggu' ? "Preview belum tersedia untuk status menunggu" : ""}
            onClick={() => setActiveTab('preview')}
            className={`flex-1 px-6 py-4 font-bold text-sm transition-all flex items-center justify-center gap-2 border-b-2 ${
              data.status === 'menunggu' 
                ? 'opacity-50 cursor-not-allowed border-transparent text-slate-400 bg-slate-50'
                : activeTab === 'preview' 
                  ? 'border-blue-600 text-blue-700 bg-white cursor-pointer' 
                  : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-100 cursor-pointer'
            }`}
          >
            <FileText className="w-4 h-4" /> Preview Surat
          </button>
        </div>

        {/* Tab Content Area */}
        <div className="relative flex-1 flex flex-col overflow-hidden">
          {/* Tab Content: Detail */}
          {activeTab === 'detail' && (
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="h-full flex flex-col">
              <CardBody className="p-6 md:p-8 flex-1 flex flex-col justify-between">
                <div className="space-y-4">
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-1">Nama Lengkap</p>
                      <p className="text-xl font-black text-slate-800 leading-none">{data.nama_lengkap}</p>
                    </div>
                    <div>
                      {getStatusBadge(data.status)}
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-3 bg-blue-50/50 p-4 rounded-xl border border-blue-100/50">
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-widest text-blue-500 mb-1">Layanan / Jenis Surat</p>
                      <p className="font-bold text-blue-900 text-sm">{data.nama_surat}</p>
                    </div>
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-widest text-blue-500 mb-1">Keperluan</p>
                      <p className="font-bold text-blue-900 text-sm line-clamp-2">{keperluanText}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-1">NIK</p>
                      <p className="font-mono font-bold text-slate-700 text-sm">{data.nik}</p>
                    </div>
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-1">No. KK</p>
                      <p className="font-mono font-bold text-slate-700 text-sm">{data.no_kk || '-'}</p>
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-1">No. HP / WA</p>
                      <p className="font-medium text-slate-700 text-sm">{data.no_hp}</p>
                    </div>
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-1">RT / RW</p>
                      <p className="font-medium text-slate-700 text-sm">{data.rt} / {data.rw}</p>
                    </div>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-1">Alamat Lengkap</p>
                    <p className="font-medium text-slate-700 text-sm">{data.alamat}</p>
                  </div>

                  {texts.length > 0 && (
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mt-3">
                      {texts.map(t => (
                        <div key={t.key}>
                          <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-1">{t.key.replace(/_/g, ' ')}</p>
                          <p className="font-medium text-slate-800 text-sm">{t.val}</p>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </CardBody>
            </motion.div>
          )}

          {/* Tab Content: Berkas */}
          {activeTab === 'berkas' && (
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="h-full flex flex-col overflow-y-auto">
              <CardBody className="p-6 md:p-8 flex-1 flex flex-col">
                {files.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-16 opacity-50 bg-slate-50 rounded-2xl border border-slate-100">
                    <ImageIcon className="w-16 h-16 text-slate-400 mb-4" />
                    <p className="text-slate-500 font-medium">Tidak ada berkas persyaratan yang dilampirkan.</p>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {files.map((file, idx) => {
                      const title = file.key.replace(/_/g, ' ').toUpperCase();
                      const fullUrl = `${BASE_URL}${file.url}`;
                      return (
                        <div 
                          key={idx} 
                          onClick={() => openViewer(title, file.url)}
                          className="group relative bg-white border border-slate-200 rounded-2xl overflow-hidden cursor-pointer hover:border-blue-400 hover:shadow-xl hover:shadow-blue-900/10 transition-all transform hover:-translate-y-1"
                        >
                          <div className="aspect-video bg-slate-100 relative overflow-hidden flex items-center justify-center">
                            <img 
                              src={fullUrl} 
                              alt={title}
                              className="object-cover w-full h-full opacity-80 group-hover:opacity-100 group-hover:scale-105 transition-all duration-500"
                              onError={(e) => {
                                e.target.style.display = 'none';
                                e.target.nextSibling.style.display = 'flex';
                              }}
                            />
                            <div className="absolute inset-0 hidden items-center justify-center bg-slate-100">
                              <FileText className="w-12 h-12 text-slate-300" />
                            </div>

                            <div className="absolute inset-0 bg-slate-900/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center backdrop-blur-[2px]">
                              <div className="bg-white/90 text-slate-800 px-4 py-2 rounded-full text-sm font-bold flex items-center gap-2 transform translate-y-4 group-hover:translate-y-0 transition-all shadow-lg">
                                <Maximize2 className="w-4 h-4" /> Perbesar Layar
                              </div>
                            </div>
                          </div>
                          <div className="p-4 border-t border-slate-100 text-center bg-white">
                            <p className="font-bold text-slate-700 text-sm truncate">{title}</p>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}

              </CardBody>
            </motion.div>
          )}

          {/* Tab Content: Tindak Lanjut */}
          {activeTab === 'tindak_lanjut' && (
            <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="h-full flex flex-col">
              <form onSubmit={handleUpdate} className="h-full flex flex-col">
                <CardBody className="p-6 md:p-8 flex-1 flex flex-col">
                  <div className="space-y-2 shrink-0 mb-5">
                    <label className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Ubah Status Menjadi</label>
                    <div className="relative">
                      <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                        {(() => {
                          switch(updateForm.status_baru) {
                            case 'menunggu': return <Clock className="w-5 h-5 text-amber-500" />;
                            case 'diproses': return <Activity className="w-5 h-5 text-blue-500" />;
                            case 'selesai': return <CheckCircle className="w-5 h-5 text-emerald-500" />;
                            case 'ditolak': return <XCircle className="w-5 h-5 text-rose-500" />;
                            default: return <Clock className="w-5 h-5 text-slate-400" />;
                          }
                        })()}
                      </div>
                      <select 
                        className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold text-slate-700 focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20 outline-none transition-all appearance-none cursor-pointer"
                        value={updateForm.status_baru}
                        onChange={(e) => setUpdateForm({...updateForm, status_baru: e.target.value})}
                        required
                      >
                        <option value="menunggu">Menunggu Verifikasi (Masuk Antrean)</option>
                        <option value="diproses">Sedang Diproses Kades (Minta TTD)</option>
                        <option value="ditolak">Tolak Berkas (Berkas Tidak Valid)</option>
                      </select>
                    </div>
                  </div>

                  {updateForm.status_baru === 'diproses' && (
                    <div className="space-y-2 shrink-0 mb-5">
                      <label className="text-[10px] font-bold uppercase tracking-widest text-slate-500 flex justify-between shrink-0">
